  plus.addEventListener('click',()=>setZoom(zoomLevels[Math.min(zoomLevels.length-1,zoomLevels.indexOf(level)+1)]))
  reset.addEventListener('click',()=>setZoom(100))
  card.resetFlyerZoom=()=>setZoom(100)
